using Path=System.IO.Path;using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Text.Json;using Fumen;using Fumen.ChartDefinition;using Fumen.Converters;using StepManiaEditor;
class Program {
 const string Input="#TITLE:Display;#BPMS:0=120,4=180;#DISPLAYBPM:*;#NOTES:dance-single::Hard:9:0,0,0,0,0:1000,0100;#NOTES:dance-single::Easy:2:0,0,0,0,0:0010,0001;";
 static async Task<object> Write(string root,string name,bool sm,bool omit,string first,string second){
 var source=Path.Combine(root,name+"-source.sm");File.WriteAllText(source,Input);var song=await new SMReader(source).LoadAsync(CancellationToken.None);
 var global=new DisplayTempo();global.FromString("*");var values=new[]{new DisplayTempo(global),new DisplayTempo(global)};values[0].FromString(first);values[1].FromString(second);
 for(var i=0;i<2;i++){song.Charts[i].Tempo=values[i].ToString();foreach(var e in song.Charts[i].Layers[0].Events)e.Extras.Clear();}
 // Original EditorSong.Save: display copied from fallback for SM, removed from
 // original song extras for SSC; EditorChart.SaveToChart sets chart.Tempo.
 song.Extras.RemoveSourceExtra(SMCommon.TagDisplayBPM);if(sm)song.Extras.AddDestExtra(SMCommon.TagDisplayBPM,song.Charts[0].Tempo);
 song.SourceType=sm?FileFormatType.SM:FileFormatType.SSC;var target=Path.Combine(root,name+(sm?".sm":".ssc"));var config=new SMWriterBase.SMWriterBaseConfig{Song=song,FilePath=target,FallbackChart=song.Charts[0],ForceOnlySongLevelTiming=omit,WriteAttacksFromFallbackChart=sm,PropertyEmissionBehavior=SMWriterBase.PropertyEmissionBehavior.Stepmania,MeasureSpacingBehavior=SMWriterBase.MeasureSpacingBehavior.UseLeastCommonMultiple};var saved=sm?new SMWriter(config).Save():new SSCWriter(config).Save();if(!saved)throw new InvalidOperationException("Original Fumen writer refused "+name);
 var reread=sm?await new SMReader(target).LoadAsync(CancellationToken.None):await new SSCReader(target).LoadAsync(CancellationToken.None);if(reread.Charts.Count!=2)throw new InvalidOperationException("Unexpected chart count");for(var i=0;i<2;i++){var expected=values[sm?0:i].ToString();if(reread.Charts[i].Tempo!=expected)throw new InvalidOperationException("Display readback mismatch "+name+" chart"+i);}var output=File.ReadAllText(target);return new {name,sm,omit,first=values[0].ToString(),second=values[1].ToString(),independent=!ReferenceEquals(values[0],values[1]),output,charts=reread.Charts.Select((c,i)=>new{chart=i,display=c.Tempo}).ToArray()};
 }
 static async Task Main(){System.Globalization.CultureInfo.DefaultThreadCurrentCulture=System.Globalization.CultureInfo.InvariantCulture;System.Globalization.CultureInfo.DefaultThreadCurrentUICulture=System.Globalization.CultureInfo.InvariantCulture;var root=Path.Combine(Path.GetTempPath(),"display-oracle-"+Guid.NewGuid());Directory.CreateDirectory(root);try{var cases=new List<object>();cases.Add(await Write(root,"ssc-local-specified",false,false,"90:180","*"));cases.Add(await Write(root,"ssc-local-actual",false,false,"","*"));cases.Add(await Write(root,"ssc-omit-equal",false,true,"90:180","90:180"));cases.Add(await Write(root,"sm-fallback-specified",true,false,"90:180","*"));cases.Add(await Write(root,"sm-fallback-actual",true,false,"","*"));Console.Write(JsonSerializer.Serialize(new{input=Input,cases}));}finally{Directory.Delete(root,true);}}
}
